use Tests\TestCase;
final class StorageVersionRecoveryTest extends TestCase {
 use DatabaseTransactions;
 private array $objects=[];private array $commands=[];private bool $corrupt=false;private ?\Closure $onPut=null;
 private function values(string $prefix=''):array{return['endpoint'=>'https://s3.oss-cn-hangzhou.aliyuncs.com','region'=>'cn-hangzhou','bucket'=>'classroom-component-tests','key'=>'TEST_KEY','secret'=>'TEST_SECRET','prefix'=>$prefix?:'tests/'.Str::uuid(),'presign_seconds'=>120];}
 private function mockS3():void{$this->app->bind(AwsS3OssStorage::class,function($app,$p){$cfg=$p['configuration'];$client=new S3Client([...AwsS3OssStorage::clientOptions($cfg),'handler'=>function($cmd,$req){$name=$cmd->getName();$key=$cmd['Bucket'].'/'.$cmd['Key'];$this->commands[]=[$name,$key];if($name==='DeleteObject'){unset($this->objects[$key]);return new FulfilledPromise(new Result([]));}if($name==='PutObject'){if($this->onPut)($this->onPut)($cmd);$this->objects[$key]=['body'=>(string)$req->getBody(),'metadata'=>$cmd['Metadata']??[],'mime'=>$cmd['ContentType']];return new FulfilledPromise(new Result(['ETag'=>'fixture']));}$o=$this->objects[$key]??throw new \RuntimeException('fixture_object_missing');if($name==='HeadObject')return new FulfilledPromise(new Result(['ContentLength'=>strlen($o['body']),'Metadata'=>$o['metadata'],'ContentType'=>$o['mime']]));if($name==='GetObject')return new FulfilledPromise(new Result(['Body'=>Utils::streamFor($this->corrupt?str_repeat('x',strlen($o['body'])):$o['body'])]));throw new \RuntimeException('fixture_command_unexpected');}]);return new AwsS3OssStorage($cfg,$client);});}
 private function lesson(string $version):object{$uid=DB::table('users')->insertGetId(['name'=>'Fixture','student_id'=>'ST'.Str::random(20),'password'=>Hash::make('valid-password'),'role'=>'user','must_change_password'=>false]);$cid=DB::table('courses')->insertGetId(['name'=>'Fixture']);$id=DB::table('lessons')->insertGetId(['name'=>'Recovery','course_id'=>$cid,'creator_id'=>$uid,'target_language'=>'zh','status'=>'live','recorder_epoch'=>1,'recorder_user_id'=>$uid,'recorder_connection'=>'fixture-device','lease_until'=>now()->addMinutes(10),'idempotency_key'=>(string)Str::uuid(),'storage_version'=>$version]);return DB::table('lessons')->find($id);}
 private function frames(object $l,int $count):array{Queue::fake();$store=new AudioStore;for($i=0;$i<$count;$i++)$store->accept($l->id,$l->creator_id,'fixture-device',1,$i,str_repeat(pack('v',1000+$i),1600));return DB::table('audio_segments')->where('lesson_id',$l->id)->orderBy('sequence')->get()->all();}
 public function test_registry_encryption_location_identity_and_credential_rotation():void{$v=$this->values();$a=StorageRegistry::register($v);$row=DB::table('storage_versions')->where('version',$a)->first();$this->assertStringNotContainsString('TEST_SECRET',$row->payload_encrypted);$this->assertStringNotContainsString($v['bucket'],$row->payload_encrypted);$this->assertSame($v['prefix'],StorageRegistry::configuration($a)->prefix);$b=StorageRegistry::register([...$v,'secret'=>'ROTATED_TEST_SECRET']);$this->assertSame($a,$b);$this->assertSame('ROTATED_TEST_SECRET',StorageRegistry::configuration($a)->secret);$this->assertSame($row->created_at,DB::table('storage_versions')->where('version',$a)->first()->created_at);$new=StorageRegistry::register([...$v,'prefix'=>$v['prefix'].'/new']);$this->assertNotSame($a,$new);$this->assertSame($v['prefix'],StorageRegistry::configuration($a)->prefix);}
 public function test_unknown_or_tampered_history_fails_without_env_fallback():void{$this->expectExceptionMessage('storage_configuration_version_unavailable');StorageRegistry::configuration(str_repeat('f',64));}
 public function test_decrypted_registry_identity_must_match_row():void{$v=$this->values();$id=StorageRegistry::register($v);DB::table('storage_versions')->where('version',$id)->update(['payload_encrypted'=>Crypt::encryptString(json_encode([...$v,'prefix'=>'other']))]);$this->expectExceptionMessage('storage_configuration_version_unavailable');StorageRegistry::resolve($id);}
 public function test_hundred_frame_chunk_and_timed_partial_keep_durable_ack_and_reduce_jobs():void{$version=StorageRegistry::register($this->values());$l=$this->lesson($version);$s=$this->frames($l,101);$chunks=DB::table('audio_chunks')->where('lesson_id',$l->id)->orderBy('id')->get();$this->assertCount(2,$chunks);$this->assertSame(100,$chunks[0]->frame_count);$this->assertSame('pending',$chunks[0]->storage_state);$this->assertSame(1,$chunks[1]->frame_count);$this->assertSame('open',$chunks[1]->storage_state);$this->assertSame(320000,filesize($s[99]->local_path)*100);$this->assertSame(316800,(int)$s[99]->offset_bytes);Queue::assertPushed(UploadChunk::class,3);Queue::assertNotPushed(UploadSegment::class);$duplicate=(new AudioStore)->accept($l->id,$l->creator_id,'fixture-device',1,100,str_repeat(pack('v',1100),1600));$this->assertTrue($duplicate['duplicate']);Queue::assertPushed(UploadChunk::class,3);AudioStore::flushEpoch($l->id,1);$this->assertSame('pending',DB::table('audio_chunks')->find($chunks[1]->id)->storage_state);Queue::assertPushed(UploadChunk::class,4);}
 public function test_upload_and_restore_missing_and_corrupt_frames_from_one_verified_chunk_get():void{$this->mockS3();$version=StorageRegistry::register($this->values());$l=$this->lesson($version);$segments=$this->frames($l,3);$chunk=DB::table('audio_chunks')->where('lesson_id',$l->id)->first();(new UploadChunk($chunk->id))->handle(new SegmentRecovery);$chunk=DB::table('audio_chunks')->find($chunk->id);$this->assertSame('uploaded',$chunk->storage_state);$expected=array_map(fn($s)=>file_get_contents($s->local_path),$segments);unlink($chunk->local_path);foreach($segments as$s)unlink($s->local_path);$recovery=new SegmentRecovery;foreach($segments as$i=>$s)$this->assertSame($expected[$i],file_get_contents($recovery->ensure($s)));$gets=array_filter($this->commands,fn($a)=>$a[0]==='GetObject');$this->assertCount(1,$gets);file_put_contents($segments[1]->local_path,str_repeat('bad',100));$this->assertSame($expected[1],file_get_contents($recovery->ensure($segments[1])));$this->assertNotEmpty(glob($segments[1]->local_path.'.corrupt-*'));}
 public function test_historical_location_remains_used_after_active_env_location_changes():void{$this->mockS3();$old=$this->values();$version=StorageRegistry::register($old);$l=$this->lesson($version);$segments=$this->frames($l,1);config(['classroom.oss'=>$this->values('different-location')]);$chunk=DB::table('audio_chunks')->where('lesson_id',$l->id)->first();(new UploadChunk($chunk->id))->handle(new SegmentRecovery);$this->assertStringContainsString('/'.$old['prefix'].'/',array_keys($this->objects)[0]);$this->assertSame($version,DB::table('audio_chunks')->find($chunk->id)->storage_version);}
 public function test_timed_partial_chunk_seals_and_later_same_epoch_frames_create_new_immutable_chunk():void{$this->mockS3();$v=StorageRegistry::register($this->values());$l=$this->lesson($v);$this->frames($l,3);$a=DB::table('audio_chunks')->where('lesson_id',$l->id)->first();(new UploadChunk($a->id))->handle(new SegmentRecovery);$a=DB::table('audio_chunks')->find($a->id);(new AudioStore)->accept($l->id,$l->creator_id,'fixture-device',1,3,str_repeat("\x04\x00",1600));$b=DB::table('audio_chunks')->where('lesson_id',$l->id)->where('group_sequence',1)->first();$this->assertSame(3,$b->first_sequence);$this->assertSame(4800,(int)$b->start_sample);$this->assertSame(1,$b->frame_count);$this->assertSame($a->sha256,DB::table('audio_chunks')->find($a->id)->sha256);$this->assertSame(3,DB::table('audio_chunks')->find($a->id)->frame_count);}
 public function test_epoch_flush_preserves_sample_timeline_without_mixing_epochs():void{$v=StorageRegistry::register($this->values());$l=$this->lesson($v);$this->frames($l,2);AudioStore::flushEpoch($l->id,1);DB::table('lessons')->where('id',$l->id)->update(['recorder_epoch'=>2,'next_sequence'=>0]);(new AudioStore)->accept($l->id,$l->creator_id,'fixture-device',2,0,str_repeat("\x01\x00",1600));$chunks=DB::table('audio_chunks')->where('lesson_id',$l->id)->orderBy('id')->get();$this->assertCount(2,$chunks);$this->assertSame('pending',$chunks[0]->storage_state);$this->assertSame(2,$chunks[1]->epoch);$this->assertSame(3200,(int)$chunks[1]->start_sample);$this->assertSame($v,$chunks[1]->storage_version);}
 public function test_archive_unknown_history_marks_failed_and_reports_specific_stable_code():void{$l=$this->lesson(str_repeat('e',64));DB::table('lessons')->where('id',$l->id)->update(['status'=>'ended','media_samples'=>1600]);try{(new ArchiveLesson($l->id))->handle(new PcmArchiveAssembler,new SegmentRecovery);$this->fail('Unknown history accepted');}catch(\RuntimeException $e){$this->assertSame('storage_configuration_version_unavailable',$e->getMessage());}$this->assertSame('failed',DB::table('lessons')->find($l->id)->archive_status);$this->assertDatabaseMissing('recordings',['lesson_id'=>$l->id]);}
 public function test_late_duplicate_failed_callback_cannot_downgrade_uploaded_chunk():void{$this->mockS3();$v=StorageRegistry::register($this->values());$l=$this->lesson($v);$this->frames($l,1);$c=DB::table('audio_chunks')->where('lesson_id',$l->id)->first();$job=new UploadChunk($c->id);$job->handle(new SegmentRecovery);$job->failed(new \RuntimeException('fixture'));$this->assertSame('uploaded',DB::table('audio_chunks')->find($c->id)->storage_state);}
 public function test_purge_marker_stops_all_storage_jobs_before_cloud_or_archive_io():void{$this->mockS3();$v=StorageRegistry::register($this->values());$l=$this->lesson($v);$s=$this->frames($l,1)[0];$c=DB::table('audio_chunks')->where('lesson_id',$l->id)->first();DB::table('lessons')->where('id',$l->id)->update(['status'=>'ended','purge_status'=>'queued']);(new UploadChunk($c->id))->handle(new SegmentRecovery);(new UploadSegment($s->id))->handle(new SegmentRecovery);(new ArchiveLesson($l->id,true))->handle(new PcmArchiveAssembler,new SegmentRecovery);$this->assertSame([],$this->commands);$this->assertSame('open',DB::table('audio_chunks')->find($c->id)->storage_state);$this->assertSame('pending',DB::table('audio_segments')->find($s->id)->storage_state);$this->assertDatabaseMissing('recordings',['lesson_id'=>$l->id]);}
 public function test_upload_archive_and_purge_share_same_lesson_data_mutex():void{$v=StorageRegistry::register($this->values());$l=$this->lesson($v);$s=$this->frames($l,1)[0];$c=DB::table('audio_chunks')->where('lesson_id',$l->id)->first();$jobs=[new UploadChunk($c->id),new UploadSegment($s->id),new ArchiveLesson($l->id),new \App\Jobs\PurgeLesson($l->id)];foreach($jobs as$j){$lock=$j->middleware()[0];$this->assertSame('lesson-data:'.$l->id,$lock->key);$this->assertTrue($lock->shareKey);$this->assertSame(7500,$lock->expiresAfter);}}
 public function test_late_failed_archive_callback_does_not_recreate_events_after_purge():void{$v=StorageRegistry::register($this->values());$l=$this->lesson($v);DB::table('lessons')->where('id',$l->id)->update(['status'=>'ended','purge_status'=>'purged','archive_status'=>'failed']);$before=DB::table('lesson_events')->where('lesson_id',$l->id)->count();(new ArchiveLesson($l->id))->failed(new \RuntimeException('fixture'));$this->assertSame($before,DB::table('lesson_events')->where('lesson_id',$l->id)->count());}
 public function test_mutex_releases_have_bounded_time_without_consuming_exception_budget():void{$jobs=[new UploadChunk(1),new UploadSegment(1),new ArchiveLesson(1)];$queue=new \Illuminate\Queue\DatabaseQueue(DB::connection(),'jobs');$queue->setContainer($this->app);foreach($jobs as$job){$deadline=$job->retryUntil()->getTimestamp();$this->travel(60)->seconds();$this->assertSame($deadline,$job->retryUntil()->getTimestamp());$id=$queue->push($job);$payload=json_decode(DB::table('jobs')->where('id',$id)->value('payload'),true);$this->assertSame(0,$payload['maxTries']);$this->assertSame($deadline,$payload['retryUntil']);$this->assertSame($job instanceof ArchiveLesson?4:6,$payload['maxExceptions']);$this->travelBack();}}
 public function test_remote_corruption_never_publishes_false_frame():void{$this->mockS3();$version=StorageRegistry::register($this->values());$l=$this->lesson($version);$s=$this->frames($l,1)[0];$chunk=DB::table('audio_chunks')->where('lesson_id',$l->id)->first();(new UploadChunk($chunk->id))->handle(new SegmentRecovery);$chunk=DB::table('audio_chunks')->find($chunk->id);unlink($chunk->local_path);unlink($s->local_path);$this->corrupt=true;try{(new SegmentRecovery)->ensure($s);$this->fail('Corrupt object accepted');}catch(\RuntimeException $e){$this->assertSame('recording_download_checksum_failed',$e->getMessage());}$this->assertFileDoesNotExist($s->local_path);$this->assertFileDoesNotExist($chunk->local_path);}
 public function test_same_recovery_instance_rechecks_modified_chunk_and_can_redownload_it():void{$this->mockS3();$v=StorageRegistry::register($this->values());$l=$this->lesson($v);$segments=$this->frames($l,2);$c=DB::table('audio_chunks')->where('lesson_id',$l->id)->first();(new UploadChunk($c->id))->handle(new SegmentRecovery);$c=DB::table('audio_chunks')->find($c->id);$expected=file_get_contents($segments[1]->local_path);unlink($c->local_path);foreach($segments as$s)unlink($s->local_path);$recovery=new SegmentRecovery;$recovery->ensure($segments[0]);$cached=RecordingPaths::chunk($c);$body=file_get_contents($cached);$body[3200]=chr(ord($body[3200])^255);file_put_contents($cached,$body);try{$path=$recovery->ensure($segments[1]);}catch(\RuntimeException $e){$this->assertSame('recording_segment_checksum_failed',$e->getMessage());$path=$recovery->ensure($segments[1]);}$this->assertSame($expected,file_get_contents($path));$this->assertCount(2,array_filter($this->commands,fn($cmd)=>$cmd[0]==='GetObject'));}
 public function test_legacy_segment_recovers_into_current_node_path_with_registered_history():void{$this->mockS3();$version=StorageRegistry::register($this->values());$l=$this->lesson($version);$pcm=str_repeat("\x01\x00",1600);$storage=StorageRegistry::resolve($version);$key=$storage->configuration->objectKey('legacy/source.pcm');$storage->put($key,$pcm,metadata:['sha256'=>hash('sha256',$pcm)]);$id=DB::table('audio_segments')->insertGetId(['lesson_id'=>$l->id,'epoch'=>1,'sequence'=>0,'start_sample'=>0,'sample_count'=>1600,'sha256'=>hash('sha256',$pcm),'local_path'=>'Z:/old-node/missing.pcm','object_key'=>$key,'storage_version'=>$version,'storage_state'=>'uploaded']);$s=DB::table('audio_segments')->find($id);$path=(new SegmentRecovery)->ensure($s);$this->assertSame($pcm,file_get_contents($path));$this->assertSame($path,DB::table('audio_segments')->find($id)->local_path);}
 public function test_reconciler_dry_run_is_nonmutating_apply_seals_abandoned_open_chunk():void{$v=StorageRegistry::register($this->values());$l=$this->lesson($v);$this->frames($l,1);$chunk=DB::table('audio_chunks')->where('lesson_id',$l->id)->first();DB::table('audio_chunks')->where('id',$chunk->id)->update(['created_at'=>now()->subSeconds(11)]);$before=DB::table('audio_chunks')->find($chunk->id);$dry=(new RecordingReconciler)->scan(false);$this->assertContains($chunk->id,$dry['open_chunks']);$this->assertSame($before->storage_state,DB::table('audio_chunks')->find($chunk->id)->storage_state);(new RecordingReconciler)->scan(true);$this->assertSame('pending',DB::table('audio_chunks')->find($chunk->id)->storage_state);Queue::assertPushed(UploadChunk::class,fn($j)=>$j->chunkId===$chunk->id);}
 public function test_real_ffmpeg_archive_rebuild_from_mock_oss_recovers_exact_pcm():void{if(!is_file(config('classroom.ffmpeg'))||!is_file(config('classroom.ffprobe')))$this->markTestSkipped('FFmpeg absent; real component archive unverified.');$this->mockS3();$v=StorageRegistry::register($this->values());$l=$this->lesson($v);$segments=$this->frames($l,20);$expected=implode('',array_map(fn($s)=>file_get_contents($s->local_path),$segments));$chunk=DB::table('audio_chunks')->where('lesson_id',$l->id)->first();(new UploadChunk($chunk->id))->handle(new SegmentRecovery);$chunk=DB::table('audio_chunks')->find($chunk->id);unlink($chunk->local_path);foreach($segments as$s)unlink($s->local_path);DB::table('lessons')->where('id',$l->id)->update(['status'=>'ended']);(new ArchiveLesson($l->id,true))->handle(new PcmArchiveAssembler,new SegmentRecovery);$this->assertSame('playable',DB::table('lessons')->find($l->id)->archive_status);$this->assertSame(hash('sha256',$expected),hash_file('sha256',RecordingPaths::archiveDirectory($l->id).'/input.pcm'));$this->assertSame(32000,DB::table('recordings')->where('lesson_id',$l->id)->value('duration_samples'));}
 public function test_scheduled_reconciliation_preserves_exhausted_failed_states_but_manual_scan_can_retry():void{
  $v=StorageRegistry::register($this->values());$l=$this->lesson($v);$s=$this->frames($l,1)[0];$c=DB::table('audio_chunks')->where('lesson_id',$l->id)->first();
  DB::table('audio_chunks')->where('id',$c->id)->update(['storage_state'=>'failed','updated_at'=>now()->subMinutes(6)]);
  DB::table('audio_segments')->where('id',$s->id)->update(['chunk_id'=>null,'offset_bytes'=>null,'storage_state'=>'failed','updated_at'=>now()->subMinutes(6)]);
  DB::table('lessons')->where('id',$l->id)->update(['status'=>'ended','archive_status'=>'failed','updated_at'=>now()->subMinutes(6)]);Queue::fake();
  (new \App\Jobs\ReconcileRecordings)->handle(new RecordingReconciler);
  Queue::assertNotPushed(UploadChunk::class,fn($j)=>$j->chunkId===$c->id);Queue::assertNotPushed(UploadSegment::class,fn($j)=>$j->segmentId===$s->id);Queue::assertNotPushed(ArchiveLesson::class,fn($j)=>(int)$j->lessonId===$l->id);$this->assertSame('failed',DB::table('audio_chunks')->find($c->id)->storage_state);$this->assertSame('failed',DB::table('audio_segments')->find($s->id)->storage_state);$this->assertSame('failed',DB::table('lessons')->find($l->id)->archive_status);
  $manual=(new RecordingReconciler)->scan(true,1000,true);$this->assertContains($c->id,$manual['uploads'],'manual chunk retry');$this->assertContains($s->id,$manual['legacy_uploads'],'manual legacy retry');$this->assertContains($l->id,$manual['archives'],'manual archive retry');Queue::assertPushed(UploadChunk::class,fn($j)=>$j->chunkId===$c->id);Queue::assertPushed(UploadSegment::class,fn($j)=>$j->segmentId===$s->id);Queue::assertPushed(ArchiveLesson::class,fn($j)=>(int)$j->lessonId===$l->id);
 }
 public function test_manual_and_scheduled_scans_share_global_cache_lock():void{
  $lock=Cache::lock('recording-reconciliation-scan',300);$this->assertTrue($lock->get());Queue::fake();try{$scan=(new RecordingReconciler)->scan(true,100,false);$this->assertSame('scan_already_running',$scan['skipped']);Queue::assertNothingPushed();}finally{$lock->release();}
 }
 public function test_purge_deletes_historical_archive_put_before_recording_publication():void{
  $this->mockS3();$old=$this->values();$v=StorageRegistry::register($old);$l=$this->lesson($v);$this->frames($l,1);$store=StorageRegistry::resolve($v);$orphan=$store->configuration->objectKey('lessons/'.$l->id.'/archive/original.m4a');$other=$store->configuration->objectKey('lessons/999999/archive/original.m4a');$store->put($orphan,'synthetic archive PUT completed before metadata');$store->put($other,'unrelated fixture');$this->assertDatabaseMissing('recordings',['lesson_id'=>$l->id]);config(['classroom.oss'=>$this->values('different-current-prefix')]);
  DB::table('lessons')->where('id',$l->id)->update(['status'=>'ended','archive_status'=>'processing','deleted_at'=>now(),'purge_status'=>'queued']);(new \App\Jobs\PurgeLesson($l->id))->handle();
  $this->assertArrayNotHasKey($old['bucket'].'/'.$orphan,$this->objects);$this->assertArrayHasKey($old['bucket'].'/'.$other,$this->objects);$this->assertSame('purged',DB::table('lessons')->find($l->id)->purge_status);$this->assertDatabaseHas('purge_objects',['lesson_id'=>$l->id,'storage_version'=>$v,'object_key'=>$orphan,'status'=>'deleted']);$deletes=array_values(array_filter($this->commands,fn($c)=>$c[0]==='DeleteObject'));$this->assertSame([['DeleteObject',$old['bucket'].'/'.$orphan]],$deletes);
 }
 public function test_purge_deletes_old_legacy_frame_put_without_persisted_key():void{
