  (new \App\Jobs\PurgeLesson($l->id))->handle();$this->assertArrayNotHasKey($old['bucket'].'/'.$orphan,$this->objects);$this->assertArrayHasKey($old['bucket'].'/'.$other,$this->objects);$this->assertDatabaseHas('purge_objects',['lesson_id'=>$l->id,'storage_version'=>$v,'object_key'=>$orphan,'status'=>'deleted']);$this->assertSame('purged',DB::table('lessons')->find($l->id)->purge_status);
 }
