 public function test_archive_cli_explicitly_retries_failed_with_audit_and_rejects_purge():void{
  $v=StorageRegistry::register($this->values());$l=$this->lesson($v);DB::table('lessons')->where('id',$l->id)->update(['status'=>'ended','archive_status'=>'failed']);Queue::fake();
  $this->assertSame(0,\Illuminate\Support\Facades\Artisan::call('classroom:archive',['lesson'=>$l->id]));$this->assertStringContainsString('Archive queued',\Illuminate\Support\Facades\Artisan::output());$this->assertSame('pending',DB::table('lessons')->find($l->id)->archive_status);Queue::assertPushed(ArchiveLesson::class,fn($j)=>(int)$j->lessonId===$l->id);$this->assertDatabaseHas('audit',['lesson_id'=>$l->id,'action'=>'recording.archive_cli_requested']);
  DB::table('lessons')->where('id',$l->id)->update(['archive_status'=>'failed','purge_status'=>'queued']);Queue::fake();$this->assertSame(1,\Illuminate\Support\Facades\Artisan::call('classroom:archive',['lesson'=>$l->id]));$this->assertStringContainsString('Lesson is scheduled for data deletion',\Illuminate\Support\Facades\Artisan::output());Queue::assertNothingPushed();$this->assertSame('failed',DB::table('lessons')->find($l->id)->archive_status);$this->assertSame(1,DB::table('audit')->where('lesson_id',$l->id)->where('action','recording.archive_cli_requested')->count());
