 public function test_reconciliation_rechecks_purge_after_each_candidate_snapshot():void{
  foreach(['open','upload','legacy','archive']as$kind){
   $v=StorageRegistry::register($this->values());$l=$this->lesson($v);$s=$this->frames($l,1)[0];$c=DB::table('audio_chunks')->where('lesson_id',$l->id)->first();
   DB::table('audio_chunks')->where('id',$c->id)->update(['storage_state'=>$kind==='open'?'open':($kind==='upload'?'pending':'uploaded'),'created_at'=>now()->subMinutes(1),'updated_at'=>now()->subMinutes(1)]);
   if($kind==='legacy')DB::table('audio_segments')->where('id',$s->id)->update(['chunk_id'=>null,'offset_bytes'=>null,'storage_state'=>'pending','updated_at'=>now()->subMinutes(1)]);
   if($kind==='archive')DB::table('lessons')->where('id',$l->id)->update(['status'=>'ended','updated_at'=>now()->subMinutes(1)]);
   $needle=match($kind){'open'=>'select "c".* from "audio_chunks" as "c"','upload'=>'select * from "audio_chunks"','legacy'=>'select * from "audio_segments"','archive'=>'select * from "lessons" where "purge_status" is null'};$hook=(object)['fired'=>false];
   DB::listen(function($query)use($hook,$needle,$l){if(!$hook->fired&&str_contains($query->sql,$needle)){$hook->fired=true;DB::table('lessons')->where('id',$l->id)->update(['purge_status'=>'queued','archive_status'=>'failed']);}});Queue::fake();
   $scan=(new RecordingReconciler)->scan(true,1000,false);$this->assertTrue($hook->fired,$kind);Queue::assertNotPushed(UploadChunk::class,fn($j)=>$j->chunkId===$c->id);Queue::assertNotPushed(UploadSegment::class,fn($j)=>$j->segmentId===$s->id);Queue::assertNotPushed(ArchiveLesson::class,fn($j)=>(int)$j->lessonId===$l->id);$this->assertNotContains($l->id,$scan['archives']);$this->assertNotContains($c->id,$scan['open_chunks']);$this->assertNotContains($c->id,$scan['uploads']);$this->assertNotContains($s->id,$scan['legacy_uploads']);$this->assertSame('failed',DB::table('lessons')->find($l->id)->archive_status);
  }
 }
