 }
 public function test_three_epochs_pause_and_recorder_change_rebuild_one_exact_timeline_from_mock_cloud():void{
  if(!is_file(config('classroom.ffmpeg'))||!is_file(config('classroom.ffprobe')))$this->markTestSkipped('FFmpeg absent; real component archive unverified.');
  $this->mockS3();$v=StorageRegistry::register($this->values());$l=$this->lesson($v);$this->frames($l,20);AudioStore::flushEpoch($l->id,1);DB::table('lessons')->where('id',$l->id)->update(['status'=>'paused']);
  try{(new AudioStore)->accept($l->id,$l->creator_id,'fixture-device',1,20,str_repeat("\x01\x00",1600));$this->fail('Paused audio accepted');}catch(\App\Domain\Failure $e){$this->assertSame('recorder_stale',$e->errorCode);}
  $second=DB::table('users')->insertGetId(['name'=>'Second recorder','student_id'=>'handoff-'.Str::random(20),'role'=>'user','password'=>Hash::make('valid-password'),'must_change_password'=>false]);
  DB::table('lessons')->where('id',$l->id)->update(['status'=>'live','recorder_epoch'=>2,'next_sequence'=>0,'recorder_user_id'=>$second,'recorder_connection'=>'second-device']);
  for($i=0;$i<20;$i++)(new AudioStore)->accept($l->id,$second,'second-device',2,$i,str_repeat(pack('v',2000+$i),1600));AudioStore::flushEpoch($l->id,2);
  try{(new AudioStore)->accept($l->id,$l->creator_id,'fixture-device',1,20,str_repeat("\x01\x00",1600));$this->fail('Former recorder epoch accepted');}catch(\App\Domain\Failure $e){$this->assertSame('recorder_stale',$e->errorCode);}
  DB::table('lessons')->where('id',$l->id)->update(['recorder_epoch'=>3,'next_sequence'=>0]);for($i=0;$i<5;$i++)(new AudioStore)->accept($l->id,$second,'second-device',3,$i,str_repeat(pack('v',3000+$i),1600));(new AudioStore)->accept($l->id,$second,'second-device',3,5,str_repeat("\x02\x00",512));AudioStore::flushEpoch($l->id,3);
  $segments=DB::table('audio_segments')->where('lesson_id',$l->id)->orderBy('start_sample')->get();$hash=hash('sha256',implode('',array_map(fn($s)=>file_get_contents($s->local_path),$segments->all())));$chunks=DB::table('audio_chunks')->where('lesson_id',$l->id)->orderBy('epoch')->get();$this->assertCount(3,$chunks);$this->assertSame([0,32000,64000],array_map(fn($c)=>(int)$c->start_sample,$chunks->all()));
  foreach($chunks as$c)(new UploadChunk($c->id))->handle(new SegmentRecovery);foreach(DB::table('audio_chunks')->where('lesson_id',$l->id)->get()as$c)unlink($c->local_path);foreach($segments as$s)unlink($s->local_path);DB::table('lessons')->where('id',$l->id)->update(['status'=>'ended']);(new ArchiveLesson($l->id,true))->handle(new PcmArchiveAssembler,new SegmentRecovery);
  $this->assertSame($hash,hash_file('sha256',RecordingPaths::archiveDirectory($l->id).'/input.pcm'));$this->assertSame(72512,DB::table('recordings')->where('lesson_id',$l->id)->value('duration_samples'));$this->assertSame('playable',DB::table('lessons')->find($l->id)->archive_status);$this->assertCount(3,array_filter($this->commands,fn($c)=>$c[0]==='GetObject'));
 }
 public function test_crashed_upload_after_object_put_reconciles_idempotently_without_timeline_loss():void{
  $this->mockS3();$v=StorageRegistry::register($this->values());$l=$this->lesson($v);$s=$this->frames($l,2);$c=DB::table('audio_chunks')->where('lesson_id',$l->id)->first();AudioStore::flushEpoch($l->id,1);$pcm=file_get_contents($s[0]->local_path).file_get_contents($s[1]->local_path);$store=StorageRegistry::resolve($v);$key=$store->configuration->objectKey('lessons/'.$l->id.'/chunks/1/0.pcm');$store->put($key,$pcm,metadata:['sha256'=>hash('sha256',$pcm)]);
  DB::table('audio_chunks')->where('id',$c->id)->update(['storage_state'=>'uploading','object_key'=>$key,'sha256'=>hash('sha256',$pcm),'updated_at'=>now()->subSeconds(151)]);$scan=(new RecordingReconciler)->scan(true);$this->assertContains($c->id,$scan['uploads']);(new UploadChunk($c->id))->handle(new SegmentRecovery);$this->assertCount(1,$this->objects);$this->assertSame('uploaded',DB::table('audio_chunks')->find($c->id)->storage_state);$this->assertSame(3200,DB::table('lessons')->find($l->id)->media_samples);$this->assertSame(hash('sha256',$pcm),DB::table('audio_chunks')->find($c->id)->sha256);
 }
